/** ядро_значення 안의 연결형 байт_значення потік_значення. Ethernet/TCP 패킷 스택이 아닌 루프백 socket шар_значення. */
public final class потік_мережа {
    static int[] Стан_значення = new int[16], порт_значення = new int[16], 짝 = new int[16], точка_порт = new int[16], хвилиноньку_панове_значення = new int[16], ІТ_відділ_границя = new int[16];
    static int[] фронтальна_камера_значення = new int[16], 수 = new int[16], дані = new int[16 * 1024];
    static int Далі_елемент = 50000;
    static int перевіряти(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && Стан_значення[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int номер_порту) { for (int цикл_індекс = 0; цикл_індекс < 16; цикл_індекс++) if (Стан_значення[цикл_індекс] != 0 && ІТ_відділ_границя[цикл_індекс] != 0 && порт_значення[цикл_індекс] == номер_порту) return true; return false; }
    public static int Створення_запис() {
        for (int цикл_індекс = 0; цикл_індекс < 16; цикл_індекс++) if (Стан_значення[цикл_індекс] == 0) { Стан_значення[цикл_індекс] = 1; точка_порт[цикл_індекс] = порт_значення[цикл_індекс] = фронтальна_камера_значення[цикл_індекс] = 수[цикл_індекс] = хвилиноньку_панове_значення[цикл_індекс] = ІТ_відділ_границя[цикл_індекс] = 0; 짝[цикл_індекс] = -1; return цикл_індекс + 40; }
        return -24;
    }
    public static int зв_язувати_учасник(int 열린파일번호, int сокет_адреса, int номер_порту) {
        int цикл_індекс = перевіряти(열린파일번호); if (цикл_індекс < 0) return -9;
        if (сокет_адреса != 0 && сокет_адреса != 0x7f000001) return -99;
        if (Стан_значення[цикл_індекс] != 1 || номер_порту < 0 || номер_порту > 65535) return -22;
        if (номер_порту == 0) { do { номер_порту = Далі_елемент++; if (Далі_елемент > 65535) Далі_елемент = 50000; } while (사용중(номер_порту)); }
        if (사용중(номер_порту)) return -98; порт_значення[цикл_індекс] = номер_порту; ІТ_відділ_границя[цикл_індекс] = 1; Стан_значення[цикл_індекс] = 2; return 0;
    }
    public static int прослуховувати_учасник(int 열린파일번호, int 연결대기한도) { int цикл_індекс = перевіряти(열린파일번호); if (цикл_індекс < 0) return -9; if (Стан_значення[цикл_індекс] != 2 || 연결대기한도 < 1) return -22; Стан_значення[цикл_індекс] = 3; return 0; }
    public static int З_єднання(int 열린파일번호, int сокет_адреса, int номер_порту) {
        int цикл_індекс = перевіряти(열린파일번호); if (цикл_індекс < 0) return -9; if (сокет_адреса != 0x7f000001) return -101;
        if (номер_порту < 1 || номер_порту > 65535 || Стан_значення[цикл_індекс] > 2) return -22;
        int отримувати_сторінка = -1; for (int внутрішнє_посада = 0; внутрішнє_посада < 16; внутрішнє_посада++) if (Стан_значення[внутрішнє_посада] == 3 && порт_значення[внутрішнє_посада] == номер_порту) отримувати_сторінка = внутрішнє_посада;
        if (отримувати_сторінка < 0) return -111;
        int 대기여부 = 0; for (int внутрішнє_посада = 0; внутрішнє_посада < 16; внутрішнє_посада++) if (хвилиноньку_панове_значення[внутрішнє_посада] == отримувати_сторінка + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (Стан_значення[цикл_індекс] == 1) { int 처리값 = зв_язувати_учасник(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int Інше = Створення_запис(); if (Інше < 0) return Інше; Інше -= 40;
        Стан_значення[цикл_індекс] = Стан_значення[Інше] = 4; 짝[цикл_індекс] = Інше; 짝[Інше] = цикл_індекс; порт_значення[Інше] = номер_порту; точка_порт[цикл_індекс] = номер_порту; точка_порт[Інше] = порт_значення[цикл_індекс]; хвилиноньку_панове_значення[Інше] = отримувати_сторінка + 1; return 0;
    }
    public static int приймати_зв_язок(int 열린파일번호) { int цикл_індекс = перевіряти(열린파일번호); if (цикл_індекс < 0) return -9; if (Стан_значення[цикл_індекс] != 3) return -22; for (int внутрішнє_посада = 0; внутрішнє_посада < 16; внутрішнє_посада++) if (Стан_значення[внутрішнє_посада] != 0 && хвилиноньку_панове_значення[внутрішнє_посада] == цикл_індекс + 1) { хвилиноньку_панове_значення[внутрішнє_посада] = 0; return внутрішнє_посада + 40; } return -11; }
    public static int Запис(int 열린파일번호, int 항목수) {
        int цикл_індекс = перевіряти(열린파일번호); if (цикл_індекс < 0) return -9; if (Стан_значення[цикл_індекс] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int внутрішнє_посада = 짝[цикл_індекс]; if (внутрішнє_посада < 0) return -32; int 총수 = 1024 - 수[внутрішнє_посада]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int Порівняння_посада = 0; Порівняння_посада < 총수; Порівняння_посада++) дані[внутрішнє_посада * 1024 + (фронтальна_камера_значення[внутрішнє_посада] + 수[внутрішнє_посада] + Порівняння_посада) % 1024] = замикання_на_себе_мережа.Уперед_значення[Порівняння_посада]; 수[внутрішнє_посада] += 총수; return 총수;
    }
    public static int Читання(int 열린파일번호, int 항목수) {
        int цикл_індекс = перевіряти(열린파일번호); if (цикл_індекс < 0) return -9; if (Стан_значення[цикл_індекс] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[цикл_індекс] == 0) return 짝[цикл_індекс] < 0 ? 0 : -11; if (항목수 > 수[цикл_індекс]) 항목수 = 수[цикл_індекс];
        for (int Порівняння_посада = 0; Порівняння_посада < 항목수; Порівняння_посада++) замикання_на_себе_мережа.Уперед_значення[Порівняння_посада] = дані[цикл_індекс * 1024 + (фронтальна_камера_значення[цикл_індекс] + Порівняння_посада) % 1024]; фронтальна_камера_значення[цикл_індекс] = (фронтальна_камера_значення[цикл_індекс] + 항목수) % 1024; 수[цикл_індекс] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int цикл_індекс = перевіряти(열린파일번호); return цикл_індекс < 0 ? -9 : порт_значення[цикл_індекс]; }
    public static int 상대창구읽기(int 열린파일번호) { int цикл_індекс = перевіряти(열린파일번호); return цикл_індекс < 0 ? -9 : точка_порт[цикл_індекс]; }
    public static int Закрити(int 열린파일번호) {
        int цикл_індекс = перевіряти(열린파일번호); if (цикл_індекс < 0) return -9;
        if (Стан_значення[цикл_індекс] == 3) for (int внутрішнє_посада = 0; внутрішнє_посада < 16; внутрішнє_посада++) if (хвилиноньку_панове_значення[внутрішнє_посада] == цикл_індекс + 1) { if (짝[внутрішнє_посада] >= 0) 짝[짝[внутрішнє_посада]] = -1; Стан_значення[внутрішнє_посада] = хвилиноньку_панове_значення[внутрішнє_посада] = ІТ_відділ_границя[внутрішнє_посада] = 0; }
        if (짝[цикл_індекс] >= 0) 짝[짝[цикл_індекс]] = -1; Стан_значення[цикл_індекс] = ІТ_відділ_границя[цикл_індекс] = 수[цикл_індекс] = хвилиноньку_панове_значення[цикл_індекс] = 0; return 0;
    }
}
